snippet_css:
:root{
  --bg: #F2E8D5;
  --fg: #5A4232;
  --muted: #4E6146;
  --surface: rgba(255,255,255,.68);
  --border: rgba(90,66,50,.24);
  --accent: #C98B7E;
  --accent-fg: #2D2118;
  --accent-grad: linear-gradient(135deg,#C98B7E,#C9A24B);
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 10px 26px rgba(90,66,50,.14);
  --btn-shadow: 0 4px 0 rgba(201,139,126,.4);
  --art-bg: radial-gradient(circle at 50% 38%,#F2E8D5 0 30%,#C9A24B 30% 31%,#E9D6A8 31% 44%,transparent 45%),linear-gradient(160deg,#E9D6A8,#C98B7E);
  --media-bg: linear-gradient(160deg,#E9D6A8,#8FA382);
  --cta-bg: linear-gradient(180deg,#F7EFDD,#E9D6A8);
  --input-bg: rgba(255,255,255,.9);
  --ok: #4E6146;
  --warn: #A85A4A;
  --font-display: 'Cinzel Decorative','Noto Serif TC',serif;
  --font-body: 'Federo','Cormorant','Noto Serif TC',serif;
  --font-mono: 'Cormorant',ui-monospace,'SFMono-Regular',monospace;
  --focus-ring: #B45E4C;
}

